package org.brightstats.model;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
import org.brightstats.model.TypedDiagram.*;
import org.brightstats.stats.*;
public final class RegressionDiagramChecks {
    private static int checks;
    private static void require(boolean condition){checks++;if(!condition)throw new AssertionError("Regression diagram contract");}
    private static void rejects(Runnable action){try{action.run();throw new AssertionError("Invalid copula diagram accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{List<String> names=List.of("X","Z","Y");var plain=DiagramTemplates.regression(names,2,new int[]{0,1},true);require(DiagramModels.regressionCopula(plain,names).isEmpty());JsonObject attached=new JsonObject();attached.addProperty("edge","path0");var properties=new JsonObject();properties.addProperty("method","TWO_STAGE_GAUSSIAN");properties.addProperty("plottingPosition","HAZEN");var document=plain.with(new Node("gc",ElementType.GAUSSIAN_COPULA,"Copula",350,350,properties)).with(new Node("anchor",ElementType.DONGLE,"",0,0,attached)).with(new Link("correction",ElementType.CONNECTION_BETWEEN_GAUSSIAN_COPULA_AND_INDEPENT_TO_DEPENDENT_LV_CONNECTION,"gc","anchor",new JsonObject()));var model=DiagramModels.regressionCopula(document,names).orElseThrow();require(model.method()==CopulaRegression.Method.TWO_STAGE_GAUSSIAN&&model.plottingPosition()==CopulaRegression.PlottingPosition.HAZEN&&Arrays.equals(model.endogenous(),new int[]{0})&&model.names().equals(List.of("X","Z")));Random random=new Random(316);double[][] x=new double[140][2];double[] y=new double[140];for(int row=0;row<x.length;row++){double error=random.nextGaussian();x[row][0]=Math.exp(.5*error+.4*random.nextGaussian());x[row][1]=random.nextGaussian();y[row]=.8*x[row][0]+.4*x[row][1]+.5*error+.2*random.nextGaussian();}require(CopulaRegression.fit(x,y,model).coefficients().size()==4);rejects(()->DiagramModels.regressionCopula(document.remove(Set.of("intercept")),names));rejects(()->DiagramModels.regressionCopula(plain.with(new Node("orphan",ElementType.GAUSSIAN_COPULA,"",0,0,new JsonObject())),names));var other=new JsonObject();other.addProperty("edge","intercept_path");rejects(()->DiagramModels.regressionCopula(document.with(new Node("anchor",ElementType.DONGLE,"",0,0,other)),names));var swapped=new Link("correction",ElementType.CONNECTION_BETWEEN_GAUSSIAN_COPULA_AND_INDEPENT_TO_DEPENDENT_LV_CONNECTION,"predictor0","anchor",new JsonObject());rejects(()->DiagramModels.regressionCopula(document.with(swapped),names));var output=Path.of(args[0]);Files.createDirectories(output);Files.writeString(output.resolve("regression-copula.json"),new GsonBuilder().setPrettyPrinting().create().toJson(document));System.out.println("{\"checks\":"+checks+",\"copula_method\":\"2sCOPE\"}");}
}
